export function getPageContent(name: string): string | undefined {
  if (name === "" || name === "index" || name === "index.html") {
    return pages["index.html"];
  }
  const clean = name.endsWith(".html") ? name : `${name}.html`;
  return pages[clean] || pages[name];
}
